import * as wt from 'node:worker_threads';

async function main(): Promise<void> {
  const channel = new wt.MessageChannel();
  const port1 = channel.port1;
  const port2 = channel.port2;
  const worker = new wt.Worker(`
    const { port } = require('node:worker_threads').workerData;
    port.on('message', (m) => { port.postMessage('echo:' + m); if (m === 'bye') port.close(); });
    port.postMessage('hello');
  `, { eval: true, workerData: { port: port2 }, transferList: [port2] });
  const exited = new Promise<number>((resolve: (code: number) => void): void => { worker.once('exit', resolve); });
  const next = (): Promise<any> => new Promise<any>((resolve: (value: any) => void): void => { port1.once('message', resolve); });
  console.log(await next());
  port1.postMessage('a');
  console.log(await next());
  const closed = new Promise<void>((resolve: () => void): void => { port1.once('close', resolve); });
  port1.postMessage('bye');
  console.log(await next());
  await closed;
  console.log('closed');
  console.log('exit', await exited);
}
